(function() {
    'use strict';

    class ResilientOrgAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Mental Health at Work: The Resilient Organization';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    titleDefault: 'Round 1: Setting the Climate',
                    briefingKey: 'r1_briefing',
                    briefingDefault: '<b>Context:</b> You are Diego/Elena Vargas, Senior Manager at Apex Tecnologia in Bogota. Your 40-person product team faces a delayed launch, recent layoffs in the adjacent department, and a new return-to-office mandate (3 days/week).<br><br><b>Scenario A — RTO Policy:</b> The return-to-office policy has generated visible tension. Several team members have long commutes or caregiving responsibilities. Leadership expects compliance. How will you handle the rollout with your team?<br><br><b>Scenario B — Laura Chen:</b> Laura, your most reliable senior engineer (4 years tenure), has started missing optional team rituals, her code reviews are slower, and she pushed back on a scope addition for the first time. Performance scores remain above average. She has not disclosed anything.',
                    primaryLabelKey: 'r1_primary_label',
                    primaryLabelDefault: 'How do you implement the RTO policy?',
                    primaryOptions: [
                        { id: 'r1pA', labelKey: 'r1pA', labelDefault: 'Enforce strictly: 3 days minimum, no exceptions — the policy is clear and applies equally to everyone', effects: { psychSafety: -10, teamPerformance: 3, wellbeingQuality: 20, attritionRisk: 12, legalCompliance: 0, managerWellbeing: -3 } },
                        { id: 'r1pB', labelKey: 'r1pB', labelDefault: 'Hold a team meeting: present the policy, listen to concerns, and collaborate on a transition plan that respects both the mandate and individual circumstances', effects: { psychSafety: 12, teamPerformance: 2, wellbeingQuality: 80, attritionRisk: -8, legalCompliance: 5, managerWellbeing: 2 } },
                        { id: 'r1pC', labelKey: 'r1pC', labelDefault: 'Quietly allow flexibility for those who ask privately, without formally communicating any adjustment', effects: { psychSafety: 3, teamPerformance: 0, wellbeingQuality: 45, attritionRisk: -2, legalCompliance: -5, managerWellbeing: -2 } },
                        { id: 'r1pD', labelKey: 'r1pD', labelDefault: 'Escalate your concerns to senior leadership and wait for further guidance before communicating anything to your team', effects: { psychSafety: -5, teamPerformance: -3, wellbeingQuality: 30, attritionRisk: 5, legalCompliance: 0, managerWellbeing: -5 } }
                    ],
                    secondaryLabelKey: 'r1_secondary_label',
                    secondaryLabelDefault: 'How do you respond to Laura?',
                    secondaryOptions: [
                        { id: 'r1sA', labelKey: 'r1sA', labelDefault: 'Note the changes in her next scheduled performance review — it may be a temporary phase', effects: { psychSafety: -3, teamPerformance: 0, wellbeingQuality: 25, attritionRisk: 5, legalCompliance: 0, managerWellbeing: 0 } },
                        { id: 'r1sB', labelKey: 'r1sB', labelDefault: 'Have an informal check-in: mention you noticed she seems quieter lately and ask how things are going, without assumptions', effects: { psychSafety: 10, teamPerformance: 2, wellbeingQuality: 85, attritionRisk: -6, legalCompliance: 0, managerWellbeing: 2 } },
                        { id: 'r1sC', labelKey: 'r1sC', labelDefault: 'Ask her teammates discreetly if they know what might be going on with Laura', effects: { psychSafety: -8, teamPerformance: -2, wellbeingQuality: 20, attritionRisk: 8, legalCompliance: -3, managerWellbeing: -2 } },
                        { id: 'r1sD', labelKey: 'r1sD', labelDefault: 'Send her a resource article about managing stress and work-life balance', effects: { psychSafety: -2, teamPerformance: 0, wellbeingQuality: 35, attritionRisk: 3, legalCompliance: 0, managerWellbeing: 0 } }
                    ],
                    feedbackKey: 'r1_feedback'
                },
                {
                    titleKey: 'r2_title',
                    titleDefault: 'Round 2: Cynicism and Erosion',
                    briefingKey: 'r2_briefing',
                    briefingDefault: '<b>Three weeks later.</b><br><br><b>Scenario A — Tomas Reyes:</b> Tomas (UX Lead, 7 years tenure) is openly negative in team meetings. He attributes the architect departure to "the same management mistakes as always." Other team members find his comments demotivating. He told a peer he is "just collecting a paycheck." His direct output remains technically competent but he has stopped collaborating on UX research synthesis.<br><br><b>Scenario B — Laura Follow-up:</b> Laura continues to show the same pattern. Her code quality remains acceptable but she has not returned to optional team activities.',
                    primaryLabelKey: 'r2_primary_label',
                    primaryLabelDefault: 'How do you address Tomas in the next team meeting?',
                    primaryOptions: [
                        { id: 'r2pA', labelKey: 'r2pA', labelDefault: 'Address it publicly: "Tomas, I need you to keep feedback constructive in team settings"', effects: { psychSafety: -8, teamPerformance: 2, wellbeingQuality: 25, attritionRisk: 10, legalCompliance: 0, managerWellbeing: -3 } },
                        { id: 'r2pB', labelKey: 'r2pB', labelDefault: 'Ignore the comment and redirect the meeting to the agenda', effects: { psychSafety: -3, teamPerformance: -4, wellbeingQuality: 20, attritionRisk: 5, legalCompliance: 0, managerWellbeing: -2 } },
                        { id: 'r2pC', labelKey: 'r2pC', labelDefault: 'Acknowledge his perspective in the meeting, then schedule a private 1-on-1 to explore what is driving his frustration and what might re-engage him', effects: { psychSafety: 10, teamPerformance: 3, wellbeingQuality: 85, attritionRisk: -8, legalCompliance: 0, managerWellbeing: 3 } },
                        { id: 'r2pD', labelKey: 'r2pD', labelDefault: 'Agree with his criticism to demonstrate empathy: "You are right, leadership has made mistakes"', effects: { psychSafety: 2, teamPerformance: -6, wellbeingQuality: 30, attritionRisk: 3, legalCompliance: 0, managerWellbeing: -4 } }
                    ],
                    secondaryLabelKey: 'r2_secondary_label',
                    secondaryLabelDefault: 'What is your next step with Laura?',
                    secondaryOptions: [
                        { id: 'r2sA', labelKey: 'r2sA', labelDefault: 'Reduce her workload immediately without consulting her', effects: { psychSafety: 0, teamPerformance: -3, wellbeingQuality: 35, attritionRisk: 2, legalCompliance: 0, managerWellbeing: 0 } },
                        { id: 'r2sB', labelKey: 'r2sB', labelDefault: 'Ask Laura what support she would find helpful and offer flexible options (schedule, workload, peer support)', effects: { psychSafety: 10, teamPerformance: 3, wellbeingQuality: 90, attritionRisk: -8, legalCompliance: 0, managerWellbeing: 3 } },
                        { id: 'r2sC', labelKey: 'r2sC', labelDefault: 'Pair her with a senior colleague as an informal mentor for peer connection', effects: { psychSafety: 5, teamPerformance: 2, wellbeingQuality: 65, attritionRisk: -4, legalCompliance: 0, managerWellbeing: 1 } },
                        { id: 'r2sD', labelKey: 'r2sD', labelDefault: 'Take no specific action — her performance metrics are still acceptable', effects: { psychSafety: -2, teamPerformance: -2, wellbeingQuality: 15, attritionRisk: 6, legalCompliance: 0, managerWellbeing: -1 } }
                    ],
                    feedbackKey: 'r2_feedback'
                },
                {
                    titleKey: 'r3_title',
                    titleDefault: 'Round 3: The Disclosure',
                    briefingKey: 'r3_briefing',
                    briefingDefault: '<b>Six weeks in.</b><br><br><b>Scenario A — Sofia Ortega:</b> Sofia (Product Analyst, 18 months tenure) has requested a private meeting. She tells you she has been experiencing anxiety attacks and that her doctor has diagnosed Generalized Anxiety Disorder. She attributes it partly to the 90-minute each-way commute combined with caring for her 5-year-old daughter. She is asking for temporary flexibility on two of her three required office days. She explicitly says she does not want HR involved.<br><br><b>Scenario B — Tomas:</b> Tomas has either begun to re-engage or continues to deteriorate, depending on your previous decisions. You must decide on a next step.',
                    primaryLabelKey: 'r3_primary_label',
                    primaryLabelDefault: 'How do you respond to Sofia?',
                    primaryOptions: [
                        { id: 'r3pA', labelKey: 'r3pA', labelDefault: 'Grant the flexibility immediately and keep everything confidential as she requested', effects: { psychSafety: 6, teamPerformance: 2, wellbeingQuality: 60, attritionRisk: -5, legalCompliance: -10, managerWellbeing: 0 } },
                        { id: 'r3pB', labelKey: 'r3pB', labelDefault: 'Thank her for the trust, discuss flexible options, and explain that you may need to involve HR to formalize a proper accommodation — but that you will involve her in that process', effects: { psychSafety: 10, teamPerformance: 3, wellbeingQuality: 90, attritionRisk: -10, legalCompliance: 10, managerWellbeing: 3 } },
                        { id: 'r3pC', labelKey: 'r3pC', labelDefault: 'Suggest she take medical leave until she feels better — the team can cover her work', effects: { psychSafety: -3, teamPerformance: -4, wellbeingQuality: 25, attritionRisk: 8, legalCompliance: -5, managerWellbeing: -2 } },
                        { id: 'r3pD', labelKey: 'r3pD', labelDefault: 'Express sympathy but explain that everyone faces commute challenges and the policy applies equally', effects: { psychSafety: -12, teamPerformance: -2, wellbeingQuality: 10, attritionRisk: 15, legalCompliance: -15, managerWellbeing: -4 } }
                    ],
                    secondaryLabelKey: 'r3_secondary_label',
                    secondaryLabelDefault: 'What do you do about Tomas?',
                    secondaryOptions: [
                        { id: 'r3sA', labelKey: 'r3sA', labelDefault: 'Have a deeper conversation about his sense of purpose and career direction at the company', effects: { psychSafety: 8, teamPerformance: 4, wellbeingQuality: 80, attritionRisk: -8, legalCompliance: 0, managerWellbeing: 2 } },
                        { id: 'r3sB', labelKey: 'r3sB', labelDefault: 'Place him on a formal performance improvement plan for his negative team impact', effects: { psychSafety: -6, teamPerformance: 2, wellbeingQuality: 20, attritionRisk: 10, legalCompliance: 0, managerWellbeing: -2 } },
                        { id: 'r3sC', labelKey: 'r3sC', labelDefault: 'Offer him a lead role on a new initiative to restore his sense of contribution', effects: { psychSafety: 5, teamPerformance: 3, wellbeingQuality: 65, attritionRisk: -5, legalCompliance: 0, managerWellbeing: 1 } },
                        { id: 'r3sD', labelKey: 'r3sD', labelDefault: 'Continue monitoring without additional intervention', effects: { psychSafety: -2, teamPerformance: -3, wellbeingQuality: 15, attritionRisk: 5, legalCompliance: 0, managerWellbeing: -2 } }
                    ],
                    feedbackKey: 'r3_feedback'
                },
                {
                    titleKey: 'r4_title',
                    titleDefault: 'Round 4: Conflict and Boundaries',
                    briefingKey: 'r4_briefing',
                    briefingDefault: '<b>Nine weeks in.</b><br><br><b>Scenario A — Andres Munoz:</b> Andres (Backend Developer, 3 years) and another developer Marco have escalating conflict — from passive-aggressive code review comments to a direct verbal confrontation witnessed by three team members. A trusted colleague tells you privately that Andres is going through a separation from his partner and has been sleeping poorly for weeks. Andres himself has not disclosed any of this.<br><br><b>Scenario B — Sofia Follow-up:</b> You need to review how the accommodation arrangement with Sofia is working and address any team equity concerns.',
                    primaryLabelKey: 'r4_primary_label',
                    primaryLabelDefault: 'How do you handle the Andres-Marco conflict?',
                    primaryOptions: [
                        { id: 'r4pA', labelKey: 'r4pA', labelDefault: 'Address the conflict as a professional behavior issue in a mediated conversation with both, and separately check in on Andres with a general wellbeing inquiry — keeping the two conversations on parallel tracks', effects: { psychSafety: 10, teamPerformance: 5, wellbeingQuality: 90, attritionRisk: -8, legalCompliance: 5, managerWellbeing: 3 } },
                        { id: 'r4pB', labelKey: 'r4pB', labelDefault: 'Tell Andres directly that you heard about his personal situation and ask how the team can support him', effects: { psychSafety: -8, teamPerformance: -2, wellbeingQuality: 30, attritionRisk: 8, legalCompliance: -5, managerWellbeing: -3 } },
                        { id: 'r4pC', labelKey: 'r4pC', labelDefault: 'Focus only on the professional conflict behavior — address it firmly but ignore the personal information entirely', effects: { psychSafety: 0, teamPerformance: 3, wellbeingQuality: 40, attritionRisk: 3, legalCompliance: 0, managerWellbeing: 0 } },
                        { id: 'r4pD', labelKey: 'r4pD', labelDefault: 'Refer both Andres and Marco to HR and step back from the situation', effects: { psychSafety: -5, teamPerformance: -3, wellbeingQuality: 25, attritionRisk: 6, legalCompliance: 3, managerWellbeing: -4 } }
                    ],
                    secondaryLabelKey: 'r4_secondary_label',
                    secondaryLabelDefault: 'How do you handle the Sofia accommodation review?',
                    secondaryOptions: [
                        { id: 'r4sA', labelKey: 'r4sA', labelDefault: 'Schedule a check-in with Sofia to review how the arrangement is working and discuss next steps together', effects: { psychSafety: 8, teamPerformance: 2, wellbeingQuality: 80, attritionRisk: -5, legalCompliance: 5, managerWellbeing: 2 } },
                        { id: 'r4sB', labelKey: 'r4sB', labelDefault: 'Make the arrangement permanent without review — she clearly needs it', effects: { psychSafety: 2, teamPerformance: -2, wellbeingQuality: 45, attritionRisk: 0, legalCompliance: -3, managerWellbeing: 0 } },
                        { id: 'r4sC', labelKey: 'r4sC', labelDefault: 'End the temporary arrangement as the initial period is over — fairness requires consistency', effects: { psychSafety: -8, teamPerformance: -3, wellbeingQuality: 15, attritionRisk: 12, legalCompliance: -10, managerWellbeing: -3 } },
                        { id: 'r4sD', labelKey: 'r4sD', labelDefault: 'Discuss the general principle of flexibility with the full team to ensure everyone feels the policy is fair', effects: { psychSafety: 3, teamPerformance: 1, wellbeingQuality: 50, attritionRisk: -2, legalCompliance: 0, managerWellbeing: 0 } }
                    ],
                    feedbackKey: 'r4_feedback'
                },
                {
                    titleKey: 'r5_title',
                    titleDefault: 'Round 5: The Mirror',
                    briefingKey: 'r5_briefing',
                    briefingDefault: '<b>Twelve weeks in.</b><br><br><b>Scenario A — You:</b> A 360-degree feedback cycle has returned results: your team rates you lower on "approachability" and "energy" than in the previous cycle. Your partner mentioned last week that you "seem absent even when home." You have been skipping lunch to review team output. You have not used the EAP benefit despite knowing it is available. The signs you have learned to recognize in your team members are now visible in yourself.<br><br><b>Scenario B — Modeling for the Team:</b> You have an upcoming all-hands meeting. You need to decide how (or whether) to acknowledge your own experience with the team.',
                    primaryLabelKey: 'r5_primary_label',
                    primaryLabelDefault: 'What do you do about your own wellbeing?',
                    primaryOptions: [
                        { id: 'r5pA', labelKey: 'r5pA', labelDefault: 'Activate the EAP benefit, schedule a counseling session, and speak with your own manager about temporarily adjusting priorities', effects: { psychSafety: 5, teamPerformance: 3, wellbeingQuality: 90, attritionRisk: -5, legalCompliance: 0, managerWellbeing: 15 } },
                        { id: 'r5pB', labelKey: 'r5pB', labelDefault: 'Push through — the team needs you at full capacity right now and the launch is too close', effects: { psychSafety: -3, teamPerformance: -4, wellbeingQuality: 15, attritionRisk: 5, legalCompliance: 0, managerWellbeing: -10 } },
                        { id: 'r5pC', labelKey: 'r5pC', labelDefault: 'Request temporary workload relief from your manager but do not seek counseling — you can manage on your own', effects: { psychSafety: 2, teamPerformance: 2, wellbeingQuality: 50, attritionRisk: -2, legalCompliance: 0, managerWellbeing: 5 } },
                        { id: 'r5pD', labelKey: 'r5pD', labelDefault: 'Take a few days off immediately without telling anyone the reason', effects: { psychSafety: -5, teamPerformance: -6, wellbeingQuality: 30, attritionRisk: 3, legalCompliance: 0, managerWellbeing: 3 } }
                    ],
                    secondaryLabelKey: 'r5_secondary_label',
                    secondaryLabelDefault: 'What do you share with the team?',
                    secondaryOptions: [
                        { id: 'r5sA', labelKey: 'r5sA', labelDefault: 'Share a calibrated message: "This quarter has been intense for all of us, myself included. I spoke with our EAP counselor and found it genuinely helpful. I encourage everyone to use this resource."', effects: { psychSafety: 12, teamPerformance: 3, wellbeingQuality: 90, attritionRisk: -8, legalCompliance: 0, managerWellbeing: 5 } },
                        { id: 'r5sB', labelKey: 'r5sB', labelDefault: 'Share extensively about your personal struggles, the 360 feedback, and how difficult things have been at home', effects: { psychSafety: -2, teamPerformance: -3, wellbeingQuality: 30, attritionRisk: 3, legalCompliance: 0, managerWellbeing: -3 } },
                        { id: 'r5sC', labelKey: 'r5sC', labelDefault: 'Say nothing about your own experience — maintain professional composure and focus the all-hands on project goals', effects: { psychSafety: -3, teamPerformance: 0, wellbeingQuality: 20, attritionRisk: 2, legalCompliance: 0, managerWellbeing: -2 } },
                        { id: 'r5sD', labelKey: 'r5sD', labelDefault: 'Announce that the team is strong and everything is under control — project a confident front', effects: { psychSafety: -5, teamPerformance: -2, wellbeingQuality: 10, attritionRisk: 4, legalCompliance: 0, managerWellbeing: -5 } }
                    ],
                    feedbackKey: 'r5_feedback'
                }
            ];

            this.FEEDBACK = {
                r1: {
                    primary: {
                        r1pA: 'Strict enforcement signals that leadership priorities override individual circumstances. While consistency has value, research shows this approach lowers psychological safety — team members learn that raising concerns is futile.',
                        r1pB: 'Excellent. Holding a collaborative discussion models the transparency and listening behavior that builds psychological safety. The JD-R model shows that even when demands cannot be fully reduced, giving voice increases perceived resources.',
                        r1pC: 'Informal flexibility helps individuals but creates information asymmetry. Team members who do not know to ask receive no benefit, and inconsistency erodes trust when discovered.',
                        r1pD: 'Waiting signals uncertainty and absence of advocacy. Your team experiences ambiguity as an additional stressor, compounding the existing JD-R demand burden.'
                    },
                    secondary: {
                        r1sA: 'Waiting for a formal review misses the window for early intervention. Early-stage exhaustion (Maslach) is the most responsive to support — delay allows progression to cynicism.',
                        r1sB: 'Well done. A non-judgmental, observation-based check-in is the evidence-based best practice. You noticed behavioral change without pathologizing it, and you created space for Laura to share or not.',
                        r1sC: 'Asking teammates about a colleague violates psychological safety norms and creates gossip risk. Laura may learn you investigated her, severely damaging trust.',
                        r1sD: 'Sending unsolicited resources can feel presumptuous and signals that you have already diagnosed her. It bypasses the conversation step that creates safety.'
                    }
                },
                r2: {
                    primary: {
                        r2pA: 'Public correction of a veteran employee experiencing burnout cynicism escalates defensiveness and confirms his belief that management is adversarial. The team reads this as unsafe.',
                        r2pB: 'Ignoring negative behavior allows it to become normalized team culture. Other team members interpret silence as endorsement or helplessness.',
                        r2pC: 'Excellent. Acknowledging his perspective publicly validates his experience (SDT relatedness), while the private conversation allows you to explore the JD-R resource depletion driving his cynicism.',
                        r2pD: 'Agreeing publicly undermines your leadership credibility and team confidence. Tomas needs meaning restoration, not validation of hopelessness.'
                    },
                    secondary: {
                        r2sA: 'Reducing workload without consultation thwarts autonomy (SDT). Even if well-intentioned, it signals that you see her as less capable.',
                        r2sB: 'Excellent. Asking what would help and offering options respects autonomy while providing resources. This is the SDT-aligned best practice for supporting early-stage burnout.',
                        r2sC: 'Peer mentoring is a good resource addition that supports relatedness. Not the strongest standalone intervention but a constructive step.',
                        r2sD: 'Inaction when behavioral signals persist risks progression from exhaustion to cynicism. Acceptable metrics do not mean acceptable wellbeing.'
                    }
                },
                r3: {
                    primary: {
                        r3pA: 'Granting flexibility is empathetic, but bypassing HR entirely means no formal accommodation record exists. If the arrangement is later questioned or if Sofia needs additional support, there is no documentation trail. NOM-035 and reasonable accommodation frameworks require organizational process.',
                        r3pB: 'Excellent. This response balances empathy, professional boundaries, legal compliance, and Sofia autonomy. You validated her trust, discussed options collaboratively, and were transparent about the need for formal process — while keeping her involved.',
                        r3pC: 'Suggesting leave when Sofia asked for flexibility removes her from work and thwarts competence and relatedness (SDT). It can feel like punishment for disclosure.',
                        r3pD: 'Dismissing a disclosed clinical condition as equivalent to ordinary commute frustration is both empathically damaging and legally risky. This response violates reasonable accommodation principles and destroys psychological safety for future disclosures.'
                    },
                    secondary: {
                        r3sA: 'Excellent. A purpose-focused conversation addresses the SDT needs for meaning and relatedness that are driving Tomas cynicism. This treats the root cause, not the symptom.',
                        r3sB: 'A PIP for burnout cynicism treats a health signal as a performance problem. This is the classic misclassification that accelerates disengagement.',
                        r3sC: 'Offering a new role can restore competence and meaning. It is a good intervention if combined with genuine conversation about what he needs.',
                        r3sD: 'Continued inaction allows further deterioration. At mid-stage burnout, the window for managerial intervention is closing.'
                    }
                },
                r4: {
                    primary: {
                        r4pA: 'Excellent. Parallel tracks — addressing professional behavior separately from wellbeing support — is the evidence-based best practice. You manage the team impact of the conflict while creating a non-judgmental opening for Andres to share if he chooses.',
                        r4pB: 'Using third-party information directly violates privacy and trust. Andres did not disclose to you, and revealing that you know creates a surveillance dynamic that damages psychological safety for the entire team.',
                        r4pC: 'Addressing the conflict alone is professionally necessary but leaves the wellbeing dimension entirely unaddressed. A general check-in would cost nothing and could open a door.',
                        r4pD: 'Referring entirely to HR abdicates your managerial responsibility. HR processes are slower and less personal. The team needs you to manage the immediate dynamic.'
                    },
