        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    psychSafety: 55,
                    teamPerformance: 72,
                    wellbeingQuality: 0,
                    wellbeingCount: 0,
                    attritionRisk: 50,
                    legalCompliance: 100,
                    managerWellbeing: 58,
                    safetyHistory: [],
                    performanceHistory: [],
                    wellbeingHistory: [],
                    attritionHistory: [],
                    legalHistory: [],
                    managerHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primaryChoice: '',
                    secondaryChoice: ''
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('scenarioTitle');
            if (titleEl) titleEl.innerHTML = round.titleDefault;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefingDefault;

            var primaryLabel = document.getElementById('primaryLabel');
            if (primaryLabel) primaryLabel.innerHTML = round.primaryLabelDefault;

            var secondaryLabel = document.getElementById('secondaryLabel');
            if (secondaryLabel) secondaryLabel.innerHTML = round.secondaryLabelDefault;

            var primaryContainer = document.getElementById('primaryOptions');
            if (primaryContainer) {
                var pHtml = '';
                for (var i = 0; i < round.primaryOptions.length; i++) {
                    var opt = round.primaryOptions[i];
                    pHtml += '<label><input type="radio" name="primaryDecision" value="' + opt.id + '"> ' + opt.labelDefault + '</label>';
                }
                primaryContainer.innerHTML = pHtml;
            }

            var secondaryContainer = document.getElementById('secondaryOptions');
            if (secondaryContainer) {
                var sHtml = '';
                for (var j = 0; j < round.secondaryOptions.length; j++) {
                    var sopt = round.secondaryOptions[j];
                    sHtml += '<label><input type="radio" name="secondaryDecision" value="' + sopt.id + '"> ' + sopt.labelDefault + '</label>';
                }
                secondaryContainer.innerHTML = sHtml;
            }

            var feedbackPanel = document.getElementById('feedbackPanel');
            if (feedbackPanel) feedbackPanel.style.display = 'none';
        }

        validateDecisions(decisions) {
            // FIX(v1.1.0): do NOT rebuild the option lists here. Rebuilding
            // replaces the radio inputs, clearing the learner's :checked
            // selection, so validation ALWAYS failed and a round could never be
            // submitted. Read the live selection directly.
            var primaryRadio = document.querySelector('input[name="primaryDecision"]:checked');
            var secondaryRadio = document.querySelector('input[name="secondaryDecision"]:checked');

            if (!primaryRadio) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_primary_warning'), 'warning'
                );
                return false;
            }
            if (!secondaryRadio) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_secondary_warning'), 'warning'
                );
                return false;
            }

            decisions.primaryChoice = primaryRadio.value;
            decisions.secondaryChoice = secondaryRadio.value;
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var primaryEffects = null;
            var secondaryEffects = null;

            for (var i = 0; i < round.primaryOptions.length; i++) {
                if (round.primaryOptions[i].id === d.primaryChoice) {
                    primaryEffects = round.primaryOptions[i].effects;
                    break;
                }
            }
            for (var j = 0; j < round.secondaryOptions.length; j++) {
                if (round.secondaryOptions[j].id === d.secondaryChoice) {
                    secondaryEffects = round.secondaryOptions[j].effects;
                    break;
                }
            }

            if (!primaryEffects) primaryEffects = { psychSafety: 0, teamPerformance: 0, wellbeingQuality: 0, attritionRisk: 0, legalCompliance: 0, managerWellbeing: 0 };
            if (!secondaryEffects) secondaryEffects = { psychSafety: 0, teamPerformance: 0, wellbeingQuality: 0, attritionRisk: 0, legalCompliance: 0, managerWellbeing: 0 };

            var safetyDelta = primaryEffects.psychSafety + secondaryEffects.psychSafety;
            var perfDelta = primaryEffects.teamPerformance + secondaryEffects.teamPerformance;
            var avgWellbeing = Math.round((primaryEffects.wellbeingQuality + secondaryEffects.wellbeingQuality) / 2);
            var attritionDelta = primaryEffects.attritionRisk + secondaryEffects.attritionRisk;
            var legalDelta = primaryEffects.legalCompliance + secondaryEffects.legalCompliance;
            var managerDelta = primaryEffects.managerWellbeing + secondaryEffects.managerWellbeing;

            ds.psychSafety = Math.max(0, Math.min(100, ds.psychSafety + safetyDelta));
            ds.teamPerformance = Math.max(0, Math.min(100, ds.teamPerformance + perfDelta));
            ds.wellbeingCount += 1;
            ds.wellbeingQuality = Math.round(((ds.wellbeingQuality * (ds.wellbeingCount - 1)) + avgWellbeing) / ds.wellbeingCount);
            ds.attritionRisk = Math.max(0, Math.min(100, ds.attritionRisk + attritionDelta));
            ds.legalCompliance = Math.max(0, Math.min(100, ds.legalCompliance + legalDelta));
            ds.managerWellbeing = Math.max(0, Math.min(100, ds.managerWellbeing + managerDelta));

            ds.safetyHistory.push(ds.psychSafety);
            ds.performanceHistory.push(ds.teamPerformance);
            ds.wellbeingHistory.push(ds.wellbeingQuality);
            ds.attritionHistory.push(ds.attritionRisk);
            ds.legalHistory.push(ds.legalCompliance);
            ds.managerHistory.push(ds.managerWellbeing);

            var roundKey = 'r' + (roundIdx + 1);
            var feedbackPrimary = '';
            var feedbackSecondary = '';
            if (this.FEEDBACK[roundKey]) {
                feedbackPrimary = this.FEEDBACK[roundKey].primary[d.primaryChoice] || '';
                feedbackSecondary = this.FEEDBACK[roundKey].secondary[d.secondaryChoice] || '';
            }
            var feedbackHtml = '<b>Primary Decision:</b> ' + feedbackPrimary + '<br><br><b>Secondary Decision:</b> ' + feedbackSecondary;
            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                feedbackText.innerHTML = feedbackHtml;
                feedbackPanel.style.display = 'block';
            }

            // FIX(v1.1.0): capture the next round NOW. The previous closure read
            // state.currentPeriod when the timer fired — after the framework had
            // incremented it — so it skipped a round and desynced the scenario
            // from scoring. Keep the 500ms delay so the feedback panel stays
            // visible before advancing. Guard on state identity so the deep-cloned
            // competition preview never mutates the live DOM, and on maxPeriods so
            // the final round does not advance past the last scenario.
            var self = this;
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    setTimeout(function() {
                        self._updateBriefing({ currentPeriod: nextPeriod });
                    }, 500);
                }
            }

            return {
                period: state.currentPeriod,
                primaryChoice: d.primaryChoice,
                secondaryChoice: d.secondaryChoice,
                safetyDelta: safetyDelta,
                perfDelta: perfDelta,
                wellbeingScore: avgWellbeing,
                psychSafety: ds.psychSafety,
                teamPerformance: ds.teamPerformance,
                wellbeingQuality: ds.wellbeingQuality,
                attritionRisk: ds.attritionRisk,
                legalCompliance: ds.legalCompliance,
                managerWellbeing: ds.managerWellbeing
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('safetyDisplay', 'domainState.psychSafety', (v) => Math.round(v) + '/100');
            uiManager.bind('performanceDisplay', 'domainState.teamPerformance', (v) => Math.round(v) + '/100');
            uiManager.bind('wellbeingDisplay', 'domainState.wellbeingQuality', (v) => v > 0 ? Math.round(v) + '/100' : '--');
            uiManager.bind('attritionDisplay', 'domainState.attritionRisk', (v) => Math.round(v) + '/100');
            uiManager.bind('legalDisplay', 'domainState.legalCompliance', (v) => Math.round(v) + '/100');
            uiManager.bind('managerDisplay', 'domainState.managerWellbeing', (v) => Math.round(v) + '/100');

            // FIX(v1.1.0): the framework's undo restores domainState/decisions but
            // does not re-invoke the adapter view, leaving a stale scenario/options.
            // Re-render on period:undone so the shown round matches currentPeriod.
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._undoBound) {
                this._undoBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
            }
        }

