        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRecord = history[history.length - 1];
            var r = lastRecord.results || {};
            var finalSafety = r.psychSafety || 55;
            var finalPerf = r.teamPerformance || 72;
            var finalWellbeing = r.wellbeingQuality || 0;
            var finalAttrition = r.attritionRisk || 50;
            var finalLegal = r.legalCompliance || 100;
            var finalManager = r.managerWellbeing || 58;

            var composite = Math.round((finalSafety + finalPerf + finalWellbeing + (100 - finalAttrition) + finalLegal + finalManager) / 6);

            var performance = 'Developing Leader';
            if (composite >= 80) performance = 'Exceptional Resilient Leader';
            else if (composite >= 65) performance = 'Effective Wellbeing Advocate';
            else if (composite >= 50) performance = 'Competent Manager';

            var insights = [];
            if (finalSafety >= 70) insights.push('Strong psychological safety — your team trusts you with vulnerability.');
            if (finalSafety < 50) insights.push('Psychological safety is low — team members may not disclose when struggling.');
            if (finalWellbeing >= 70) insights.push('High intervention quality — your responses were empathetic and well-calibrated.');
            if (finalWellbeing < 40) insights.push('Intervention quality needs improvement — consider the balance between empathy and professional boundaries.');
            if (finalAttrition <= 35) insights.push('Low attrition risk — your decisions helped retain talent.');
            if (finalAttrition > 65) insights.push('High attrition risk — key team members may leave due to unaddressed concerns.');
            if (finalLegal >= 90) insights.push('Strong legal compliance — accommodation and documentation decisions were sound.');
            if (finalLegal < 70) insights.push('Legal compliance gaps — some decisions created exposure under accommodation frameworks.');
            if (finalManager >= 70) insights.push('Good manager self-care — you modeled the behaviors you expect from your team.');
            if (finalManager < 45) insights.push('Manager wellbeing is depleted — sustainable leadership requires self-care.');

            return {
                compositeScore: composite,
                performance: performance,
                finalSafety: finalSafety,
                finalPerf: finalPerf,
                finalWellbeing: finalWellbeing,
                finalAttrition: finalAttrition,
                finalLegal: finalLegal,
                finalManager: finalManager,
                insights: insights
            };
        }

        getHint(state, results) {
